-- 775 sản phẩm · 10720 biến thể · 1480 ảnh
SET NAMES utf8mb4;
SET time_zone = "+00:00";
START TRANSACTION;

-- 1. Thương hiệu
ON DUPLICATE KEY UPDATE name = VALUES(name);

-- 2. Danh mục (chỉ thêm nếu chưa có slug)

-- 3. Màu (chỉ thêm nếu chưa có tên)

-- 4. Size (hệ EU; cập nhật thứ tự sắp xếp cho cả size đã có để sắp đúng 24 → 46)
ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
UPDATE sizes SET sort_order = CAST(label AS DECIMAL(5,1)) * 10 WHERE `system` = "EU" AND label REGEXP "^[0-9]+(\\.[0-9])?$";

-- 5. Dọn lần nhập trước (id 1000..100999); biến thể/ảnh/tồn kho xóa theo cascade
DELETE FROM inventory_movements WHERE ref_type = "migration";
DELETE FROM products WHERE id BETWEEN 1000 AND 100999;

-- 6. Sản phẩm

-- 7. Biến thể + tồn kho: nạp vào bảng tạm rồi ghép với colors/sizes
DROP TEMPORARY TABLE IF EXISTS stg_variant;
CREATE TEMPORARY TABLE stg_variant (product_id BIGINT UNSIGNED, sku VARCHAR(64), color_name VARCHAR(60), size_label VARCHAR(20), price BIGINT UNSIGNED, compare_at BIGINT UNSIGNED NULL, stock INT, weight INT) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SELECT s.product_id, s.sku, c.id, z.id, s.price, s.compare_at, NULL, s.weight, 1, NOW(), NOW()
FROM stg_variant s
JOIN (SELECT name, MIN(id) id FROM colors GROUP BY name) c ON c.name = s.color_name
JOIN sizes z ON z.`system` = 'EU' AND z.label = s.size_label;
SELECT v.id, s.stock, 0, 5, 0, NOW(), NOW() FROM stg_variant s JOIN product_variants v ON v.sku = s.sku;
SELECT v.id, 'receipt', s.stock, 'Tồn đầu kỳ khi nhập dữ liệu crawl (số lượng giả định)', 'migration', s.product_id, NULL, NOW() FROM stg_variant s JOIN product_variants v ON v.sku = s.sku WHERE s.stock > 0;
-- kiểm tra: mọi dòng staging đều ghép được (không mất biến thể)
SELECT COUNT(*) AS staged, (SELECT COUNT(*) FROM product_variants WHERE product_id >= 1000) AS inserted FROM stg_variant;

-- 8. Ảnh sản phẩm (tệp nằm ở storage/app/public/products/{id}/)
DROP TEMPORARY TABLE IF EXISTS stg_image;
CREATE TEMPORARY TABLE stg_image (product_id BIGINT UNSIGNED, color_name VARCHAR(60) NULL, path VARCHAR(255), alt VARCHAR(255), sort_order INT, is_primary TINYINT, width INT NULL, height INT NULL, size_bytes INT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SELECT s.product_id, c.id, s.path, s.alt, s.sort_order, s.is_primary, s.width, s.height, s.size_bytes, NOW(), NOW()
FROM stg_image s LEFT JOIN (SELECT name, MIN(id) id FROM colors GROUP BY name) c ON c.name = s.color_name;

COMMIT;
